import{K as r,a as l,c as i,b as a,k as n,q as s,ac as c}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Word 样式、多级编号与自动目录","description":"用标题样式建立文档结构，统一正文格式，将多级编号绑定标题，生成更新自动目录并排查目录缺失和编号混乱。","frontmatter":{"title":"Word 样式、多级编号与自动目录","description":"用标题样式建立文档结构，统一正文格式，将多级编号绑定标题，生成更新自动目录并排查目录缺失和编号混乱。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Word 文档排版","summary":"用标题样式建立文档结构，统一正文格式，将多级编号绑定标题，生成更新自动目录并排查目录缺失和编号混乱。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"Word 基础编辑、段落与页面设置","link":"/tools/office/word/editing"},"next":{"text":"Word 分节、页眉页脚与页码","link":"/tools/office/word/sections"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Word 基础编辑、段落与页面设置","link":"/tools/office/word/editing"},"next":{"text":"Word 分节、页眉页脚与页码","link":"/tools/office/word/sections"}},"headers":[],"relativePath":"tools/office/word/styles.md","filePath":"tools/office/word/styles.md"}'),d={name:"tools/office/word/styles.md"},g=Object.assign(d,{setup(h){const o={path:"/tools/office/word/styles",app:"Word",title:"让标题和目录一起自动维护",steps:[{tab:"开始",command:"样式",setting:"一级标题：标题 1；二级标题：标题 2",anchor:"walkthrough-1"},{tab:"开始",command:"修改样式",setting:"对象：标题 1；统一字号与段前间距",anchor:"walkthrough-2"},{tab:"引用",command:"目录",setting:"自动目录；更新方式：更新整个目录",anchor:"walkthrough-3"}]};return(p,e)=>{const t=r("OfficeGuide");return l(),i("div",null,[e[0]||(e[0]=a("h1",{id:"word-样式、多级编号与自动目录",tabindex:"-1"},[n("Word 样式、多级编号与自动目录 "),a("a",{class:"header-anchor",href:"#word-样式、多级编号与自动目录","aria-label":'Permalink to "Word 样式、多级编号与自动目录"'},"​")],-1)),e[1]||(e[1]=a("p",null,"长文档先建立结构，再安排外观。本篇以“项目总结”为例，包含“项目背景、执行过程、结果与计划”三个一级标题，每章各有两个二级标题。",-1)),s(t,{guide:o}),e[2]||(e[2]=c('<h2 id="headings" tabindex="-1">把文字变成真正的标题 <a class="header-anchor" href="#headings" aria-label="Permalink to &quot;把文字变成真正的标题 {#headings}&quot;">​</a></h2><ol><li>输入文档标题和章节标题，每个标题独占一个段落。</li><li>文档名可使用“标题”样式；章节使用“标题 1”，章节内的小节使用“标题 2”。不要把文档名也当成第一章。</li><li>打开“视图 → 导航窗格”，切换到标题视图。应该能看到三章及其小节。</li><li>点击导航项检查是否定位正确。若某段正文也出现在导航中，检查它是否误用了标题样式或大纲级别。</li><li>修改某个标题的文字，确认导航中的文字随之变化。</li></ol><p>只把文字加粗放大，不会自动建立标题层级。层级表达内容关系，应按 1 → 2 → 3 顺序使用，不因为字号偏好从“标题 1”直接跳到“标题 4”。</p><h2 id="style" tabindex="-1">统一样式 <a class="header-anchor" href="#style" aria-label="Permalink to &quot;统一样式 {#style}&quot;">​</a></h2><p>在“开始 → 样式”中右击“标题 1 → 修改”，设置字体、字号、颜色和段前段后。选择只应用于当前文档，避免无意影响以后新建文件；需要长期复用时再保存模板。对正文样式同样设置字体、行距和段落间距。</p><p>如果某些标题没有跟着变化，先确认样式正确，再检查直接格式是否覆盖了样式。选中异常标题，重新应用样式并清理不需要的局部格式。不要反复用格式刷维护几十个标题，那会让样式失去统一管理的意义。</p><h2 id="numbering" tabindex="-1">把多级编号关联到标题 <a class="header-anchor" href="#numbering" aria-label="Permalink to &quot;把多级编号关联到标题 {#numbering}&quot;">​</a></h2><p>在已经应用标题样式的基础上，使用“开始 → 多级列表”，选择与标题样式对应的方案，例如 <code>1</code>、<code>1.1</code>、<code>1.1.1</code>。需要自定义时打开“定义新的多级列表”，展开更多选项，把第一级链接到“标题 1”，第二级链接到“标题 2”。</p><p>第二级编号应包含第一级编号，并在新的第一级后重新开始；一级编号变化时二级编号才会跟着变化。缩进和编号后跟随的制表符要在同一对话框中设置，不在每个标题中补空格。</p><p>不要手动输入“1.1”，然后再启用自动编号，否则可能出现重复数字。复制其他文档的标题后，先检查是否带入另一套列表定义；必要时用当前文档的样式和多级列表重新关联。</p><h2 id="toc" tabindex="-1">插入与更新目录 <a class="header-anchor" href="#toc" aria-label="Permalink to &quot;插入与更新目录 {#toc}&quot;">​</a></h2><ol><li>在需要放目录的位置新建一段，通常位于封面之后、正文之前。</li><li>选择“引用 → 目录 → 自动目录”，或在自定义目录中设置显示级别。</li><li>增加一节内容并改变后面页数，右击目录选择“更新域/更新目录”。</li><li>只改变页码时可更新页码；标题文字或层级变化时应更新整个目录。</li><li>检查目录链接、页码和缩进；目录的外观通过目录样式管理，不在目录结果中直接改字。</li></ol><p>自动目录依赖标题结构，缺失条目时先检查标题样式，再检查目录显示级别。正文被收入目录时，检查它的大纲级别。目录本身是生成结果，手动输入的修正可能在下次更新时消失。<a href="https://support.microsoft.com/en-us/office/insert-a-table-of-contents-882e8564-0edb-435e-84b5-1d8552ccf0c0" target="_blank" rel="noopener noreferrer">微软自动目录说明</a></p><h2 id="template" tabindex="-1">模板与交付 <a class="header-anchor" href="#template" aria-label="Permalink to &quot;模板与交付 {#template}&quot;">​</a></h2><p>当样式、页边距和目录结构已稳定，可把空白内容框架另存为 <code>.dotx</code> 模板。模板保留章节占位、常用样式和说明，删除真实客户信息及旧批注。以后通过模板新建文档，不直接覆盖原模板。</p><p>交付前更新目录和其他引用字段，再导出 PDF。正文里的字段、页眉页脚和文本框不是始终处在同一选择范围内，不能仅凭在正文按一次全选和更新就认定所有字段都已刷新。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>建立三个一级标题和六个二级标题，生成显示两级的目录。在第一章和第二章之间插入新章；后续编号、目录文字和页码应在更新后同步变化。把“标题 1”改成另一种颜色，所有一级标题应一起变化。</p><p>最后删除一个章节，并更新整个目录。目录中不应再出现已删标题；若出现，检查是否只更新了页码。</p><h2 id="walkthrough" tabindex="-1">图示跟做：让标题和目录一起自动维护 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：让标题和目录一起自动维护 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：给结构赋予标题样式 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：给结构赋予标题样式 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：开始 → 样式。</strong></p><p>输入“项目背景、实施计划、风险与行动”三个一级标题，在实施计划下输入两个小节。逐个选中标题段落，分别套用标题 1、标题 2；随后在“视图”中打开导航窗格，确认层级出现。仅加粗、放大字号的文字不会自动成为标题。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：从样式修改全部同级标题 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：从样式修改全部同级标题 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：开始 → 修改样式。</strong></p><p>右击样式库中的标题 1，选择修改，调整字号和字体，再进入格式里的段落设置。确认所有一级标题一起变化，而二级标题仍保持自己的格式。若某个标题不跟随变化，检查是否存在直接格式；在练习副本中清除该段的直接格式后重新应用样式。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：生成目录并做变更验证 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：生成目录并做变更验证 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：引用 → 目录。</strong></p><p>把光标放在目录页，选择“引用 → 目录 → 自动目录”。随后修改一个标题文字，并在前面插入一页内容，右击目录选择更新域或更新目录，再选更新整个目录。验收时同时看标题文字和页码是否改变，只有页码更新不代表新增标题已收录。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>目录多出正文段落时，检查该段是否误用标题样式或大纲级别。不要直接删除目录里的某一行，下一次更新会重新生成它；应该修正正文结构。</p>',32))])}}});export{u as __pageData,g as default};
